class Solution {
public:
    int minCut(string s) {
        int n = s.size();
        vector<vector<bool>> pal(n, vector<bool>(n, false));
        // pal[i][j]：s[i..j] 是否回文，i 必须从后往前推
        for (int i = n - 1; i >= 0; --i)
            for (int j = i; j < n; ++j)
                if (s[i] == s[j] && (j - i <= 2 || pal[i + 1][j - 1])) pal[i][j] = true;

        vector<int> dp(n, 0);
        for (int i = 0; i < n; ++i) {
            if (pal[0][i]) continue;
            dp[i] = i;
            for (int j = 0; j < i; ++j)
                if (pal[j + 1][i]) dp[i] = min(dp[i], dp[j] + 1);
        }
        return dp[n - 1];
    }
};

