class Solution {
public:
    int maxProfit(int k, vector<int>& prices) {
        if (prices.empty() || k == 0) return 0;
        const long long NEG = -1000000000000000000LL;
        vector<long long> hold(k + 1, NEG), cash(k + 1, 0);
        for (int p : prices) {
            vector<long long> nh = hold, nc = cash;
            // 用上一日快照更新，避免同一天反复买卖被多算成几笔
            for (int j = 1; j <= k; ++j) {
                nh[j] = max(hold[j], cash[j - 1] - p);
                nc[j] = max(cash[j], hold[j] + p);
            }
            hold = nh;
            cash = nc;
        }
        long long ans = 0;
        for (long long v : cash) ans = max(ans, v);
        return (int)ans;
    }
};

