class Solution {
public:
    int rob(vector<int>& nums) {
        int n = nums.size();
        if (n == 1) return nums[0];
        return max(line(nums, 0, n - 1), line(nums, 1, n));
    }

private:
    int line(vector<int>& nums, int lo, int hi) {
        int prev = 0, cur = 0;
        for (int i = lo; i < hi; ++i) {
            int nxt = max(cur, prev + nums[i]);
            prev = cur;
            cur = nxt;
        }
        return cur;
    }
};

