struct TreeNode {
    int val;
    TreeNode *left, *right;
    TreeNode(int v) : val(v), left(nullptr), right(nullptr) {}
};

TreeNode* build(const vector<string>& vals) {
    if (vals.empty() || vals[0] == "null") return nullptr;
    TreeNode* root = new TreeNode(stoi(vals[0]));
    queue<TreeNode*> q;
    q.push(root);
    int i = 1, n = vals.size();
    while (!q.empty() && i < n) {
        TreeNode* node = q.front();
        q.pop();
        if (i < n) {
            if (vals[i] != "null") {
                node->left = new TreeNode(stoi(vals[i]));
                q.push(node->left);
            }
            ++i;
        }
        if (i < n) {
            if (vals[i] != "null") {
                node->right = new TreeNode(stoi(vals[i]));
                q.push(node->right);
            }
            ++i;
        }
    }
    return root;
}

pair<int, int> dfs(TreeNode* node) {
    if (!node) return {0, 0};
    pair<int, int> l = dfs(node->left), r = dfs(node->right);
    int take = node->val + l.second + r.second;
    int skip = max(l.first, l.second) + max(r.first, r.second);
    return {take, skip};
}

