    int lastStoneWeightII(vector<int>& stones) {
        int total = 0;
        for (int w : stones) total += w;
        int half = total / 2;
        vector<int> dp(half + 1, 0);
        for (int w : stones)
            for (int j = half; j >= w; --j) dp[j] = max(dp[j], dp[j - w] + w);
        return total - 2 * dp[half];
    }
